export const IG_DESKTOP_HTML = "<div class=\"bc\"><a href=\"{{home}}\">Home</a><span>›</span><a href=\"{{help}}\">Help</a><span>›</span><b>eSIM setup guide</b></div>\n\n<div class=\"main\">\n\n<aside class=\"side\">\n  <div class=\"side-card\">\n    <div class=\"side-lbl\">On this page</div>\n    <div class=\"toc\">\n      <a href=\"#chuan-bi\" class=\"toc-l\"><i>1</i> Before you install</a>\n      <a href=\"#cai-dat\" class=\"toc-l\"><i>2</i> Installation steps</a>\n      <a href=\"#kich-hoat\" class=\"toc-l\"><i>3</i> Activate on arrival</a>\n      <a href=\"#su-co\" class=\"toc-l\"><i>4</i> Troubleshooting</a>\n      <a href=\"#diem-den\" class=\"toc-l\"><i>5</i> Notes by destination</a>\n      <a href=\"#faq\" class=\"toc-l\"><i>6</i> FAQ</a>\n    </div>\n  </div>\n\n  <div class=\"side-card prg\">\n    <div class=\"ring\" id=\"ring\"><b id=\"ringP\">0%</b></div>\n    <div class=\"prg-t\"><b id=\"ringL\">Not started</b>Progress counts the steps you have marked as done.</div>\n  </div>\n\n  <div class=\"side-help\">\n    <div class=\"t\">Need someone to walk you through it?</div>\n    <p>The esim.vn support team is on 24/7 and replies in under 5 minutes on average, even outside office hours.</p>\n    <a href=\"#\" data-open-chat class=\"btn btn-y btn-sm\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z\"/></svg>Chat with an agent</a>\n  </div>\n</aside>\n\n<main>\n\n  <div class=\"hero\">\n    <span class=\"hero-ico\"><svg width=\"27\" height=\"27\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"5\" y=\"2\" width=\"14\" height=\"20\" rx=\"3\"/><path d=\"M12 18h.01\"/><path d=\"M9 6h6\"/></svg></span>\n    <h1>How to install an eSIM on iOS and Android</h1>\n  </div>\n\n  <section class=\"sec\" id=\"chuan-bi\">\n    <div class=\"sec-hd\">\n      <span class=\"sec-ico\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 2h12l2 5H4L6 2z\"/><rect x=\"2\" y=\"7\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M12 11v6M9 14h6\"/></svg></span>\n      <h2 class=\"sec-lbl\">What do you need before you start?</h2>\n    </div>\n    <p class=\"sec-sub\">Just these four things. Tap each box to mark it done.</p>\n\n    <div class=\"chks\">\n      <div class=\"chk\" data-chk role=\"checkbox\" tabindex=\"0\" aria-checked=\"false\">\n        <span class=\"chk-box\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff500\" stroke-width=\"3.4\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></span>\n        <div><div class=\"chk-t\">Your phone supports eSIM</div><div class=\"chk-d\">Dial <code>*#06#</code> on the phone keypad — if you see <b>EID</b> you are good to go.</div></div>\n      </div>\n      <div class=\"chk\" data-chk role=\"checkbox\" tabindex=\"0\" aria-checked=\"false\">\n        <span class=\"chk-box\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff500\" stroke-width=\"3.4\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></span>\n        <div><div class=\"chk-t\">Your phone is not carrier-locked</div><div class=\"chk-d\">Carrier-locked phones bought in Japan, the US or Korea will not accept another carrier’s eSIM.</div></div>\n      </div>\n      <div class=\"chk\" data-chk role=\"checkbox\" tabindex=\"0\" aria-checked=\"false\">\n        <span class=\"chk-box\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff500\" stroke-width=\"3.4\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></span>\n        <div><div class=\"chk-t\">A stable Wi-Fi connection</div><div class=\"chk-d\">Install at home before your trip, don’t wait until the airport.</div></div>\n      </div>\n      <div class=\"chk\" data-chk role=\"checkbox\" tabindex=\"0\" aria-checked=\"false\">\n        <span class=\"chk-box\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff500\" stroke-width=\"3.4\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></span>\n        <div><div class=\"chk-t\">You have the email with your eSIM</div><div class=\"chk-d\">esim.vn sends it within <b>30 seconds</b> of payment.</div></div>\n      </div>\n    </div>\n\n    <div class=\"notice\">\n      <svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#D97706\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 16v-4M12 8h.01\"/></svg>\n      <div><b>Install now, use later.</b> Installing your eSIM today is fine even if you fly next week. The plan only starts counting days once your phone picks up a network at your destination — or activates by itself 30 days after purchase.</div>\n    </div>\n\n    <div class=\"blk\">\n      <div class=\"pg-title\">Not sure about something? Tap for an explanation</div>\n      <div class=\"prep\">\n        <button class=\"prep-btn\" data-modal=\"eid\">\n          <span class=\"prep-ico\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"5\" y=\"2\" width=\"14\" height=\"20\" rx=\"2\"/><path d=\"M12 18h.01M9 6h6M9 10h6\"/></svg></span>\n          <span class=\"prep-label\">Does my phone have eSIM?</span>\n        </button>\n        <button class=\"prep-btn\" data-modal=\"code\">\n          <span class=\"prep-ico\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"M2 7l10 6 10-6\"/></svg></span>\n          <span class=\"prep-label\">Where do I get my eSIM?</span>\n        </button>\n        <button class=\"prep-btn\" data-modal=\"term\">\n          <span class=\"prep-ico\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9.1 9a3 3 0 015.8 1c0 2-3 3-3 3M12 17h.01\"/></svg></span>\n          <span class=\"prep-label\">What are SM-DP+ and ICCID?</span>\n        </button>\n      </div>\n    </div>\n\n</section>\n\n  <section class=\"sec\" id=\"cai-dat\">\n    <div class=\"sec-hd\">\n      <span class=\"sec-ico\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 11l3 3L22 4\"/><path d=\"M21 12v7a2 2 0 01-2 2H5a2 2 0 01-2-2V5a2 2 0 012-2h11\"/></svg></span>\n      <h2 class=\"sec-lbl\">How do I install the eSIM on my phone?</h2>\n    </div>\n    <p class=\"sec-sub\">Choose your phone and how to install. Every step has a picture with the button to tap highlighted.</p>\n\n    <div class=\"pg-title\">Choose your device type</div>\n    <div class=\"tabs\" id=\"devTabs\">\n      <button class=\"tab on\" data-dev=\"iphone\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M17.05 12.54c-.02-2.3 1.88-3.4 1.96-3.46-1.07-1.56-2.73-1.78-3.32-1.8-1.41-.14-2.76.83-3.48.83-.72 0-1.83-.81-3.01-.79-1.55.02-2.98.9-3.77 2.29-1.61 2.79-.41 6.92 1.15 9.19.77 1.11 1.68 2.35 2.87 2.31 1.15-.05 1.59-.74 2.98-.74 1.39 0 1.78.74 3 .72 1.24-.02 2.02-1.13 2.78-2.24.88-1.28 1.24-2.53 1.26-2.59-.03-.01-2.41-.93-2.42-3.72zM14.79 5.87c.64-.77 1.07-1.85.95-2.92-.92.04-2.03.61-2.69 1.38-.59.68-1.11 1.78-.97 2.83 1.02.08 2.07-.52 2.71-1.29z\"/></svg>iPhone / iPad</button>\n      <button class=\"tab\" data-dev=\"samsung\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linejoin=\"round\"><rect x=\"6.2\" y=\"2\" width=\"11.6\" height=\"20\" rx=\"2.6\"/><path d=\"M10.2 4.6h3.6\"/></svg>Samsung</button>\n      <button class=\"tab\" data-dev=\"pixel\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linejoin=\"round\"><rect x=\"6.2\" y=\"2\" width=\"11.6\" height=\"20\" rx=\"3.2\"/><circle cx=\"12\" cy=\"18.4\" r=\"1.15\" fill=\"currentColor\" stroke=\"none\"/></svg>Google Pixel</button>\n      <button class=\"tab\" data-dev=\"android\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M17.6 9.48l1.84-3.18a.38.38 0 00-.66-.38l-1.87 3.23a11.4 11.4 0 00-9.82 0L5.22 5.92a.38.38 0 10-.66.38L6.4 9.48A10.8 10.8 0 001 18h22a10.8 10.8 0 00-5.4-8.52zM7 15.25a1.25 1.25 0 110-2.5 1.25 1.25 0 010 2.5zm10 0a1.25 1.25 0 110-2.5 1.25 1.25 0 010 2.5z\"/></svg>Other Android</button>\n    </div>\n\n    <div class=\"pg-title\">Installation method</div>\n    <div class=\"mts\" id=\"mtCards\">\n      <button class=\"mt on\" data-mt=\"quick\">\n        <span class=\"mt-bdg\">Fastest</span>\n        <span class=\"mt-i\" aria-hidden=\"true\">i</span>\n        <span class=\"mt-tip\"><b>Fastest — about 30 seconds.</b> Tap a button in the email and your phone opens the eSIM setup screen with everything filled in — nothing to type.\n          <span class=\"row\"><span>Needs: the email open on that same phone</span><span>iOS 17.4+ / Android 10+</span></span></span>\n        <span class=\"mt-ico\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M13 2L4.1 12.7a1 1 0 00.8 1.6H11l-1 7.7 8.9-10.7a1 1 0 00-.8-1.6H12l1-7.7z\"/></svg></span>\n        <span class=\"mt-t\">Quick install button</span>\n        <span class=\"mt-d\">Tap a button in the email and the eSIM installs itself.</span>\n      </button>\n      <button class=\"mt\" data-mt=\"qr\">\n        <span class=\"mt-i\" aria-hidden=\"true\">i</span>\n        <span class=\"mt-tip\"><b>Most common — about 2 minutes.</b> Open the QR code on a computer and scan it with your phone. You need two screens at once.\n          <span class=\"row\"><span>Needs: a second screen</span><span>Good for older phones</span></span></span>\n        <span class=\"mt-ico\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"/><path d=\"M14 14h3v3h-3zM20 14h1M14 20h3M20 17v4\"/></svg></span>\n        <span class=\"mt-t\">Scan QR code</span>\n        <span class=\"mt-d\">Open the QR code on a computer and scan it with your phone.</span>\n      </button>\n      <button class=\"mt\" data-mt=\"manual\">\n        <span class=\"mt-i\" aria-hidden=\"true\">i</span>\n        <span class=\"mt-tip\"><b>Backup method — about 3 minutes.</b> Paste the two lines of code from the email into your phone yourself. A little slower, but the result is exactly the same as the other two.\n          <span class=\"row\"><span>Needs: the email with the activation code</span><span>When the QR code won’t scan</span></span></span>\n        <span class=\"mt-ico\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2.5\"/><path d=\"M6 10h.01M10 10h.01M14 10h.01M18 10h.01M7 14h10\"/></svg></span>\n        <span class=\"mt-t\">Enter manually</span>\n        <span class=\"mt-d\">Copy the 2 lines of code from the email when the QR code won’t scan.</span>\n      </button>\n    </div>\n\n    <div class=\"pbar\">\n      <span class=\"pbar-l\" id=\"pbL\">Step 0 <span>/ 0</span></span>\n      <span class=\"pbar-tr\"><i class=\"pbar-fl\" id=\"pbF\"></i></span>\n      <span class=\"pbar-p\" id=\"pbP\">0%</span>\n      <button class=\"btn btn-g btn-sm\" id=\"pbR\" type=\"button\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 12a9 9 0 103-6.7L3 8\"/><path d=\"M3 3v5h5\"/></svg>Start over</button>\n    </div>\n\n    <div id=\"steps\"></div>\n\n    <div class=\"done\" id=\"donePanel\">\n      <span class=\"done-ico\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 11-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg></span>\n      <div>\n        <div class=\"done-t\">Done! 🎉 The eSIM is now on your phone</div>\n        <div class=\"done-d\" id=\"doneTxt\"></div>\n        <div class=\"done-acts\">\n          <a href=\"#kich-hoat\" class=\"btn btn-k btn-sm\">See what to do on arrival</a>\n          <a href=\"#diem-den\" class=\"btn btn-o btn-sm\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M2 12h20M12 2a15 15 0 010 20M12 2a15 15 0 000 20\"/></svg>See notes by destination</a>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"sec\" id=\"kich-hoat\">\n    <div class=\"sec-hd\">\n      <span class=\"sec-ico\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12.55a11 11 0 0114.08 0\"/><path d=\"M1.42 9a16 16 0 0121.16 0\"/><path d=\"M8.53 16.11a6 6 0 016.95 0\"/><circle cx=\"12\" cy=\"20\" r=\"1\" fill=\"#111\"/></svg></span>\n      <h2 class=\"sec-lbl\">What to do after you land?</h2>\n    </div>\n    <p class=\"sec-sub\">Installed does not mean connected yet. Do the 3 things below — it takes less than a minute.</p>\n\n    <div class=\"step\">\n      <div class=\"step-l\"><div class=\"step-n\">1</div><div class=\"step-ln\"></div></div>\n      <div class=\"step-b\">\n        <div>\n          <h3 class=\"step-t\">Turn on data roaming for the esim.vn eSIM</h3>\n          <div class=\"step-d\">This is the most common mistake. A travel eSIM <b>must</b> have roaming on to connect — and it does <b>not</b> cost you anything extra, because the plan is prepaid.</div>\n          <div class=\"paths\">\n            <div class=\"pbx\" id=\"pbxIos\">\n              <b><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M17.05 12.54c-.02-2.3 1.88-3.4 1.96-3.46-1.07-1.56-2.73-1.78-3.32-1.8-1.41-.14-2.76.83-3.48.83-.72 0-1.83-.81-3.01-.79-1.55.02-2.98.9-3.77 2.29-1.61 2.79-.41 6.92 1.15 9.19.77 1.11 1.68 2.35 2.87 2.31 1.15-.05 1.59-.74 2.98-.74 1.39 0 1.78.74 3 .72 1.24-.02 2.02-1.13 2.78-2.24.88-1.28 1.24-2.53 1.26-2.59-.03-.01-2.41-.93-2.42-3.72zM14.79 5.87c.64-.77 1.07-1.85.95-2.92-.92.04-2.03.61-2.69 1.38-.59.68-1.11 1.78-.97 2.83 1.02.08 2.07-.52 2.71-1.29z\"/></svg> iPhone</b>\n              <span>Settings</span> › <span>Cellular</span> › <span>esim.vn</span> › <span>Cellular Data Options</span> › turn on <span>Data Roaming</span>\n            </div>\n            <div class=\"pbx\" id=\"pbxAnd\" hidden>\n              <b><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M17.6 9.48l1.84-3.18a.38.38 0 00-.66-.38l-1.87 3.23a11.4 11.4 0 00-9.82 0L5.22 5.92a.38.38 0 10-.66.38L6.4 9.48A10.8 10.8 0 001 18h22a10.8 10.8 0 00-5.4-8.52zM7 15.25a1.25 1.25 0 110-2.5 1.25 1.25 0 010 2.5zm10 0a1.25 1.25 0 110-2.5 1.25 1.25 0 010 2.5z\"/></svg> Android</b>\n              <span>Settings</span> › <span>Connections</span> / <span>Network &amp; Internet</span> › <span>Mobile networks</span> › turn on <span>Data Roaming</span>\n            </div>\n          </div>\n        </div>\n        <div class=\"illus\" id=\"actIllus\"></div>\n      </div>\n    </div>\n\n    <div class=\"step\">\n      <div class=\"step-l\"><div class=\"step-n\">2</div><div class=\"step-ln\"></div></div>\n      <div class=\"step-b\">\n        <div>\n          <h3 class=\"step-t\">Choose the esim.vn eSIM as your data line</h3>\n          <div class=\"step-d\">Your phone now has 2 SIMs/eSIMs. Let the esim.vn eSIM handle data, and keep your Vietnamese SIM as it is for bank messages and OTP codes.</div>\n          <div class=\"hint h-warn\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg><span id=\"actHint\">Remember to turn off <b>“Allow Cellular Data Switching”</b> — if it stays on, your phone may switch back to the Vietnamese SIM and you will pay very expensive roaming charges.</span></div>\n        </div>\n        <div class=\"illus\" id=\"actIllus2\"></div>\n      </div>\n    </div>\n\n    <div class=\"step\">\n      <div class=\"step-l\"><div class=\"step-n\">3</div></div>\n      <div class=\"step-b\">\n        <div>\n          <h3 class=\"step-t\">Check that you are online</h3>\n          <div class=\"step-d\">Open any website in your browser. If it loads, you’re done. If not, <b>turn airplane mode on for 15 seconds, then off</b> — this makes the phone search for networks again and fixes most cases.</div>\n        </div>\n        <div class=\"illus\" id=\"actIllus3\"></div>\n      </div>\n    </div>\n\n    <div class=\"blk\">\n      <div class=\"pg-title\">Signs that your eSIM is working</div>\n      <div class=\"signs\">\n        <div class=\"sign\">\n          <span class=\"sic\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16A34A\" stroke-width=\"2.2\" stroke-linecap=\"round\"><path d=\"M5 12.5a10 10 0 0114 0M8.5 16a5 5 0 017 0M12 19.5h.01M2 9a15 15 0 0120 0\"/></svg></span>\n          <b>An unfamiliar carrier name appears</b>For example “SoftBank”, “AIS”, “Vodafone” — that is the local carrier your eSIM is using.\n        </div>\n        <div class=\"sign\">\n          <span class=\"sic\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16A34A\" stroke-width=\"2.2\" stroke-linecap=\"round\"><path d=\"M4 20V10M10 20V4M16 20v-7M22 20h-1\"/></svg></span>\n          <b>A 4G / 5G icon appears</b>If you only see an “E” or nothing at all, the signal is not stable yet — toggle airplane mode.\n        </div>\n        <div class=\"sign\">\n          <span class=\"sic\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16A34A\" stroke-width=\"2.2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/></svg></span>\n          <b>Any website loads</b>This is the surest test — don’t just look at the signal bars.\n        </div>\n      </div>\n    </div>\n\n    <div class=\"blk\">\n      <div class=\"pg-title\">When does your plan start counting days?</div>\n      <div class=\"tl\">\n        <div class=\"tli\"><span class=\"dot\">1</span><b>Just paid</b><p>Get the eSIM by email in 30 seconds</p></div>\n        <div class=\"tli\"><span class=\"dot\">2</span><b>Installed at home</b><p>No days used yet</p></div>\n        <div class=\"tli\"><span class=\"dot\">3</span><b>In the air</b><p>The eSIM is still not counting days</p></div>\n        <div class=\"tli\"><span class=\"dot\">4</span><b>Just landed</b><p>Turn on roaming → days start counting</p></div>\n        <div class=\"tli\"><span class=\"dot\">5</span><b>Plan expires</b><p>Connection stops, top up if needed</p></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"sec\" id=\"su-co\">\n    <div class=\"sec-hd\">\n      <span class=\"sec-ico\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.7 6.3a1 1 0 000 1.4l1.6 1.6a1 1 0 001.4 0l3.77-3.77a6 6 0 01-7.94 7.94l-6.91 6.91a2.12 2.12 0 01-3-3l6.91-6.91a6 6 0 017.94-7.94l-3.76 3.76z\"/></svg></span>\n      <h2 class=\"sec-lbl\">Having trouble? Find your situation</h2>\n    </div>\n    <p class=\"sec-sub\">The eight situations below make up over 90% of support cases, and each one explains <b>why it happens</b> before the fix.</p>\n\n    <div class=\"acc\">\n      <button class=\"acc-q\"><span class=\"acc-qi\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#DC2626\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M13 2L4.1 12.7a1 1 0 00.8 1.6H11l-1 7.7 8.9-10.7a1 1 0 00-.8-1.6H12l1-7.7z\"/></svg></span>I tapped the quick install button but nothing happened<svg class=\"cvr\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></button>\n      <div class=\"acc-a\">\n        <span class=\"why\">Why</span>\n        <p>The quick install button only works when you tap it <b>on the very phone you are installing on</b>, and browsers inside chat apps often block it.</p>\n        <ol>\n          <li>Don’t open the email in Zalo/Messenger. Open it in the <b>Gmail app</b> or in <b>Chrome/Safari</b>.</li>\n          <li>iPhone needs <b>iOS 17.4 or later</b>; Android needs <b>Android 10 or later</b> and a recent SIM Manager. On older phones, use the QR code method.</li>\n          <li>Check that you tapped the right button for your phone: the iOS one or the Android one.</li>\n          <li>Still not working? Switch to <b>Scan QR code</b> — the result is exactly the same.</li>\n        </ol>\n      </div>\n    </div>\n\n    <div class=\"acc\">\n      <button class=\"acc-q\"><span class=\"acc-qi\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#DC2626\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"/><path d=\"M14 14h7v7h-7z\"/></svg></span>I scanned the QR code but the phone doesn’t recognise it<svg class=\"cvr\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></button>\n      <div class=\"acc-a\">\n        <span class=\"why\">Why</span>\n        <p>The camera needs a QR code that is big, sharp and glare-free. A code shown on another phone’s screen is usually too small.</p>\n        <ol>\n          <li>Open the QR code on a <b>computer screen</b> instead of a phone, zoomed in all the way.</li>\n          <li>Turn the brightness of the screen showing the code all the way up.</li>\n          <li>Hold the phone 15–20 cm away, not too close.</li>\n          <li>Still not working? Use the method <b>Enter manually</b>.</li>\n        </ol>\n      </div>\n    </div>\n\n    <div class=\"acc\">\n      <button class=\"acc-q\"><span class=\"acc-qi\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#DC2626\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg></span>Error “Unable to add cellular plan” / “Invalid code”<svg class=\"cvr\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></button>\n      <div class=\"acc-a\">\n        <span class=\"why\">Why</span>\n        <p>Three common causes: the code was already installed on another phone, the phone has no internet, or a character was missed when typing it in.</p>\n        <ol>\n          <li>Check that the phone really is on Wi-Fi (try opening a website).</li>\n          <li>If entering it by hand: use the <b>Copy</b> button in the email instead of typing, and watch the <code>$</code> sign and upper/lower case.</li>\n          <li>If you have installed this code on another phone before: a code works only <b>once</b>. Contact support to get a new code.</li>\n          <li>Restart the phone and try once more.</li>\n        </ol>\n      </div>\n    </div>\n\n    <div class=\"acc\">\n      <button class=\"acc-q\"><span class=\"acc-qi\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#DC2626\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M5 12.5a10 10 0 0114 0M12 19.5h.01\"/><path d=\"M2 2l20 20\"/></svg></span>Installed, but no connection on arrival<svg class=\"cvr\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></button>\n      <div class=\"acc-a\">\n        <span class=\"why\">Why</span>\n        <p>This is the number 1 case and is almost always because <b>data roaming is not on</b>, or the phone is still using data from the Vietnamese SIM.</p>\n        <ol>\n          <li>Turn on <b>Data Roaming</b> for the esim.vn eSIM only.</li>\n          <li>Set <b>Cellular Data</b> = esim.vn, not the Vietnamese SIM.</li>\n          <li>Turn airplane mode on for 15 seconds, then off, and wait 1–2 minutes for the phone to find a network.</li>\n          <li>Check that the eSIM has its <b>line turned on</b> and is not switched off.</li>\n          <li>Still nothing: go to network selection, switch from “Automatic” to picking a local carrier manually.</li>\n        </ol>\n      </div>\n    </div>\n\n    <div class=\"acc\">\n      <button class=\"acc-q\"><span class=\"acc-qi\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#DC2626\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"M2 7l10 6 10-6\"/></svg></span>I didn’t get the email with my eSIM<svg class=\"cvr\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></button>\n      <div class=\"acc-a\">\n        <span class=\"why\">Why</span>\n        <p>The email contains a QR code, so filters sometimes move it to Spam, or the email address was mistyped at checkout.</p>\n        <ol>\n          <li>Look in <b>Spam</b>, <b>Promotions</b>, <b>Updates</b> (in Gmail), search for: <code>esim.vn</code>.</li>\n          <li>No need to wait for the email — sign in to esim.vn and go to <b>Profile → Manage eSIM</b>; the codes and the quick install button are always there.</li>\n        </ol>\n      </div>\n    </div>\n\n    <div class=\"acc\">\n      <button class=\"acc-q\"><span class=\"acc-qi\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#DC2626\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"5\" y=\"2\" width=\"14\" height=\"20\" rx=\"3\"/><path d=\"M9 12l2 2 4-4\"/></svg></span>My phone has no “Add eSIM” option in Settings<svg class=\"cvr\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></button>\n      <div class=\"acc-a\">\n        <span class=\"why\">Why</span>\n        <p>Either the phone does not support eSIM, it is carrier-locked by a foreign carrier, or its software is too old.</p>\n        <ol>\n          <li>Dial <code>*#06#</code> — if there is no <b>EID</b> line, the phone has no eSIM.</li>\n          <li>Update the operating system to the latest version and check again.</li>\n          <li>Phones bought in Japan, the US or Korea are often carrier-locked — they must be unlocked first.</li>\n        </ol>\n      </div>\n    </div>\n\n    <div class=\"acc\">\n      <button class=\"acc-q\"><span class=\"acc-qi\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#DC2626\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M12 2v4M12 18v4M2 12h4M18 12h4\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/></svg></span>Unstable connection, on and off<svg class=\"cvr\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></button>\n      <div class=\"acc-a\">\n        <span class=\"why\">Why</span>\n        <p>The phone is torn between two SIMs, or is holding on to a local carrier with a weak signal where you are.</p>\n        <ol>\n          <li>Turn the Vietnamese SIM line off completely while travelling (keep the SIM, just switch it off for now).</li>\n          <li>Go to network selection, turn off “Automatic” and try the other local carriers one by one.</li>\n          <li>A weak signal indoors, in basements or on the subway is normal.</li>\n        </ol>\n      </div>\n    </div>\n\n    <div class=\"acc\">\n      <button class=\"acc-q\"><span class=\"acc-qi\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#DC2626\" stroke-width=\"2\" stroke-linecap=\"round\"><rect x=\"2\" y=\"7\" width=\"20\" height=\"10\" rx=\"2\"/><path d=\"M6 12h4M14 12h4\"/></svg></span>I want to move my eSIM to another phone<svg class=\"cvr\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></button>\n      <div class=\"acc-a\">\n        <span class=\"why\">Sorry</span>\n        <p>esim.vn travel eSIMs <b>work on one device only</b> and currently <b>cannot be moved to another phone yet</b>. An installation code also works only once.</p>\n        <ol>\n          <li>Make sure you install the eSIM on the phone you will take on the trip.</li>\n          <li><b>Don’t delete the eSIM</b> from the phone — once deleted, the old code cannot be installed again.</li>\n          <li>If a second device needs internet, <b>share Wi-Fi</b> (hotspot) from the phone with the eSIM. It is free and uses your plan’s data.</li>\n        </ol>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"sec\" id=\"diem-den\">\n    <div class=\"sec-hd\">\n      <span class=\"sec-ico\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M2 12h20M12 2a15 15 0 010 20M12 2a15 15 0 000 20\"/></svg></span>\n      <h2 class=\"sec-lbl\">Destinations that work differently</h2>\n    </div>\n    <p class=\"sec-sub\">Same eSIM, different rules in each place — these are the ones that catch travellers out.</p>\n\n    <div class=\"dst\">\n      <div class=\"dcard\"><div class=\"dflag-row\"><span class=\"dflag\" title=\"HK\"><svg viewBox=\"0 0 640 480\" preserveAspectRatio=\"xMidYMid slice\" width=\"100%\" height=\"100%\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M0 0h640v480H0\" fill=#ec1b2e /><path d=\"M346 103c-79-5-115 99-40 137-26-22-21-55-10-72l1 1c-13 24-11 53 11 71-12-12-9-39 13-49s23-39 16-49q-15-26 9-39m-38 61-5 7-2-8-8-2 8-5-1-9 6 6 9-3-4 8 6 7z\" fill=#fff id=flhk-a /><use href=#flhk-a transform=\"rotate(72 313 244)\"/><use href=#flhk-a transform=\"rotate(144 313 244)\"/><use href=#flhk-a transform=\"rotate(216 313 244)\"/><use href=#flhk-a transform=\"rotate(288 313 244)\"/></svg></span><span class=\"dflag\" title=\"TW\"><svg viewBox=\"0 0 640 480\" preserveAspectRatio=\"xMidYMid slice\" width=\"100%\" height=\"100%\" aria-hidden=\"true\" focusable=\"false\"><clipPath id=fltw-a><path d=\"M0 0h640v480H0z\"/></clipPath><g clip-path=url(#fltw-a)><path d=\"M0 0h720v480H0z\" fill=red /><path d=\"M0 0h360v240H0z\" fill=#000095 /><g fill=#fff><path d=\"m154 127-2 10 9 2-2-7zm47 5-2 7 9-3-2-9zm-42-24-5 5 2 7z\"/><path d=\"m156 120-2 7 5 5z\"/><path d=\"m154 113-7 7 7 7 2-7zm14 28 5 5 7-2zm19 5 10 3 2-10-7 2z\"/><path d=\"m192 141 7-2 2-7zm-31-2 3 9 9-2-5-5zm19 5 7 2 5-5z\"/><path d=\"m173 146 7 7 7-7-7-2zm-12-45-9 3 2 9 5-5zm-2 31 2 7 7 2zm45-12 2-7-5-5z\"/><path d=\"m168 99-7 2-2 7zm33 9-2-7-7-2zm5 19 7-7-7-7-2 7z\"/><path d=\"m201 108-9-9-12-3-12 3-9 9-3 12 3 12 9 9 12 3 12-3 9-9 3-12z\"/><path d=\"m201 132 5-5-2-7zm5-19 3-10-10-2 2 7zm-7-12-3-10-9 3 5 5zm-26-7-10-3-2 10 7-2zm7 2-7-2-5 5z\"/><path d=\"m187 94-7-7-7 7 7 2z\"/><path d=\"m192 99-5-5-7 2zm-19 47-10 3 5 16 12-12zm-5 19 12 45 12-45-12-12zm-7-26-9-3-5 17 16-4z\"/><path d=\"m147 153-12 45 33-33-4-17zm-12-21-33 33 45-12 4-16z\"/><path d=\"m154 127-7-7-12 12 16 5zm0-14-2-9-17 4 12 12z\"/><path d=\"m135 108-45 12 45 12 12-12zm90 24-17 5 5 16 45 12z\"/><path d=\"m199 139-3 9 17 5-4-16zm-12 7-7 7 12 12 5-17zm19-19 3 10 16-5-12-12zm-14 38 33 33-12-45-16-4zm7-64 9 2 5-16-16 4z\"/><path d=\"m225 108 33-33-45 12-4 16zm-12-21 12-45-33 33 5 16zm12 45 45-12-45-12-12 12z\"/><path d=\"m206 113 7 7 12-12-17-4zm-38-38-33-33 12 45 16 4zm-7 26 3-9-17-5 4 16zm-14-14-45-12 33 33 16-4zm40 7 9-2-4-17-12 12z\"/><path d=\"m192 75-12-45-12 45 12 12z\"/><path d=\"m173 94 7-7-12-12-4 16z\"/></g><circle r=51 cy=120 cx=180 fill=#000095 /><circle r=45 cy=120 cx=180 fill=#fff /></g></svg></span><span class=\"dflag\" title=\"MO\"><svg viewBox=\"0 0 640 480\" preserveAspectRatio=\"xMidYMid slice\" width=\"100%\" height=\"100%\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M0 0h640v480H0z\" fill=#00785e /><path d=\"m295 109 41 29-16-47-15 47 40-29z\" fill=#fbd116 /><g id=flmo-a><path d=\"M320 332H218l-4-4h106l1 2zm0-32 1-7-1-4a82 82 0 0 1-32 19l-24 3h-63l6 8h61q31 0 52-19m-110-24-9 2a81 81 0 0 0 61 27 81 81 0 0 0 58-25l5-59a441 441 0 0 0-5-67c-7 6-19 18-25 38l-3 23a81 81 0 0 0 14 45 81 81 0 0 1-17-49q0-19 7-35l-7-13a81 81 0 0 0-10 40q0 28 15 48a95 95 0 0 0-73-29l7 8a95 95 0 0 1 68 30 95 95 0 0 0-61-22 95 95 0 0 0-36 7 81 81 0 0 0 82 52l-14 1a81 81 0 0 1-57-22m110 88h-53a144 144 0 0 0 53 10l1-4zm0-24h-94l8 6h86l1-3zm0 12h-77l15 8h62l1-4z\" fill=#fff /><path d=\"m201 175 25 23-7-34-14 32 30-17zm36-32h35l-28-21 11 34 11-33z\" fill=#fbd116 /></g><use href=#flmo-a transform=\"matrix(-1 0 0 1 640 0)\"/></svg></span></div><h3>Hong Kong / Taiwan / Macau</h3><span class=\"dtag dtag-kyc\"><svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"2\"/><circle cx=\"9\" cy=\"10\" r=\"2\"/><path d=\"M3 20s1-3 6-3 6 3 6 3\"/></svg>Identity verification needed</span><p>You may need to register with your passport on the local carrier’s website before using the eSIM. It is free and approved within minutes.</p></div>\n      <div class=\"dcard\"><span class=\"dflag\" title=\"CN\"><svg viewBox=\"0 0 640 480\" preserveAspectRatio=\"xMidYMid slice\" width=\"100%\" height=\"100%\" aria-hidden=\"true\" focusable=\"false\"><defs><path d=\"M-.6.8 0-1 .6.8-1-.3h2z\" fill=#ff0 id=flcn-a /></defs><path d=\"M0 0h640v480H0z\" fill=#ee1c25 /><use href=#flcn-a transform=\"matrix(71.9991 0 0 72 120 120)\" height=20 width=30 /><use href=#flcn-a transform=\"rotate(239 133.7 -44)scale(23.99992 23.99978)\" height=20 width=30 /><use href=#flcn-a transform=\"rotate(-98.1 185.6 -77)scale(24 23.9997)\" height=20 width=30 /><use href=#flcn-a transform=\"rotate(-74 255.4 -107)scale(23.99998 23.99972)\" height=20 width=30 /><use href=#flcn-a transform=\"rotate(-51.3 344.8 -141.8)scale(23.99989 23.99982)\" height=20 width=30 /></svg></span><h3>China</h3><span class=\"dtag dtag-ok\"><svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>No VPN needed</span><p>The esim.vn China eSIM works with <b>TikTok, ChatGPT, Google, Gemini, Claude</b>,… without being blocked.</p></div>\n      <div class=\"dcard\"><span class=\"dflag\" title=\"VN\"><svg viewBox=\"0 0 640 480\" preserveAspectRatio=\"xMidYMid slice\" width=\"100%\" height=\"100%\" aria-hidden=\"true\" focusable=\"false\"><defs><clipPath id=flvn-a><path d=\"M-85 0h682v512H-85z\"/></clipPath></defs><g transform=translate(80)scale(.9375) clip-path=url(#flvn-a) fill-rule=evenodd><path d=\"M-128 0h768v512h-768z\" fill=#da251d /><path d=\"m350 381-90-67-89 68 33-110-89-68 110-1 34-109 35 109h110l-88 69z\" fill=#ff0 /></g></svg></span><h3>Domestic eSIM</h3><span class=\"dtag dtag-kyc\"><svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"2\"/><circle cx=\"9\" cy=\"10\" r=\"2\"/><path d=\"M3 20s1-3 6-3 6 3 6 3\"/></svg>Identity verification needed</span><p>Under Vietnamese regulations, every customer must verify their identity. Install the carrier’s app to verify with NFC.</p></div>\n    </div>\n\n    <div class=\"notice n-info\">\n      <svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#3B82F6\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 16v-4M12 8h.01\"/></svg>\n      <div><b>Please note:</b> esim.vn travel eSIM plans include <b>mobile data</b> only, with no phone number. You keep your Vietnamese SIM for OTP codes and call over Zalo, Messenger or WhatsApp as usual.</div>\n    </div>\n  </section>\n\n  <section class=\"sec\" id=\"faq\">\n    <div class=\"sec-hd\">\n      <span class=\"sec-ico\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#111\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9.1 9a3 3 0 015.8 1c0 2-3 3-3 3M12 17h.01\"/></svg></span>\n      <h2 class=\"sec-lbl\">FAQ</h2>\n    </div>\n    <p class=\"sec-sub\">In the order travellers usually ask: before buying → while installing → during the trip.</p>\n\n    <div class=\"faq-list\">\n      <div class=\"fq\">\n        <button class=\"fq-q\">Should I install the eSIM before I go or when I arrive?<span class=\"fq-ic\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></span></button>\n        <div class=\"fq-a\">Install it at home beforehand, while you have stable Wi-Fi. Installing does <b>not</b> make the plan start counting days — it only runs once the phone picks up a network at your destination. Waiting until the airport is the biggest risk, because airport Wi-Fi is often unreliable.</div>\n      </div>\n      <div class=\"fq\">\n        <button class=\"fq-q\">Do I have to take out my Vietnamese SIM?<span class=\"fq-ic\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></span></button>\n        <div class=\"fq-a\">No. The eSIM runs alongside the physical SIM. You keep your Vietnamese number for bank messages and OTP codes, and just switch <b>mobile data</b> to the travel eSIM.</div>\n      </div>\n      <div class=\"fq\">\n        <button class=\"fq-q\">How soon do I get the eSIM after paying?<span class=\"fq-ic\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></span></button>\n        <div class=\"fq-a\">About <b>30 seconds</b>. The eSIM is sent automatically to the email you used at checkout, with a QR code and quick install buttons for iOS/Android. If you can’t see the email, you can find it right away in <b>Profile → Manage eSIM</b> on the esim.vn website.</div>\n      </div>\n      <div class=\"fq\">\n        <button class=\"fq-q\">When does the plan start counting days?<span class=\"fq-ic\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></span></button>\n        <div class=\"fq-a\">From the moment the eSIM picks up its first carrier network at your destination — usually as soon as you turn on data roaming after landing. If you buy it and leave it unused, the plan activates by itself <b>30 days</b> after the purchase date.</div>\n      </div>\n      <div class=\"fq\">\n        <button class=\"fq-q\">Will turning on roaming cost me roaming charges?<span class=\"fq-ic\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></span></button>\n        <div class=\"fq-a\">No, with an esim.vn eSIM <b>you pay nothing extra</b> — the plan is already prepaid. Just make sure roaming is on for <b>eSIM esim.vn</b>, not for the Vietnamese SIM (it is the Vietnamese SIM that your home carrier charges very expensive roaming for).</div>\n      </div>\n      <div class=\"fq\">\n        <button class=\"fq-q\">How many phones can one eSIM be used on?<span class=\"fq-ic\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></span></button>\n        <div class=\"fq-a\">Only <b>one phone</b>, and it cannot be moved to another phone yet. If a second device needs internet, share Wi-Fi from the phone with the eSIM — it is free and uses your plan’s data.</div>\n      </div>\n      <div class=\"fq\">\n        <button class=\"fq-q\">Can I make calls and send texts?<span class=\"fq-ic\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></span></button>\n        <div class=\"fq-a\">esim.vn travel eSIM plans currently include mobile data only, without their own phone number. You call and message over Zalo, Messenger, WhatsApp and FaceTime as usual using the plan’s data.</div>\n      </div>\n      <div class=\"fq\">\n        <button class=\"fq-q\">How long does 1GB last?<span class=\"fq-ic\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></span></button>\n        <div class=\"fq-a\">A realistic estimate: 1GB covers about 3 hours of maps, 200 messages with photos, or 1 hour of standard-quality video. Travellers usually use <b>0.5–1GB/day</b>. If you watch a lot of video or share Wi-Fi with other devices, choose an unlimited plan.</div>\n      </div>\n      <div class=\"fq\">\n        <button class=\"fq-q\">Can I reinstall an eSIM after deleting it?<span class=\"fq-ic\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"6 9 12 15 18 9\"/></svg></span></button>\n        <div class=\"fq-a\"><b>No.</b> The QR code and activation code work only once. If you delete the eSIM from your phone by mistake, contact support to see whether a new code can be issued — don’t delete it without asking first.</div>\n      </div>\n    </div>\n  </section>\n\n</main>\n</div>\n\n<section class=\"band\">\n  <div class=\"band-in\">\n    <div>\n      <h2>No plan for your next trip yet?</h2>\n      <p>More than 250 countries and territories. Get your eSIM by email within 30 seconds of payment.</p>\n    </div>\n    <div class=\"band-acts\">\n      <a href=\"{{destinations}}\" class=\"btn btn-k\">See all destinations</a>\n      <a href=\"{{calc}}\" class=\"btn btn-o\">Data calculator</a>\n    </div>\n  </div>\n</section>\n\n\n\n\n\n<div class=\"ov\" id=\"ov-eid\">\n  <div class=\"mdl\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"t-eid\">\n    <div class=\"mdl-hd\"><div class=\"mdl-t\" id=\"t-eid\">Does my phone support eSIM?</div><button class=\"mdl-x\" data-close=\"eid\" aria-label=\"Close\" type=\"button\"><svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg></button></div>\n    <div class=\"mdl-b\">\n      <div class=\"msec\"><div class=\"msec-l\">The quickest check</div>\n        <div class=\"mrow\"><div class=\"mdot\"></div><span>Open the phone keypad and dial <b>*#06#</b>. If the screen that appears shows an <b>EID</b> line (32 digits), your phone <b>has eSIM</b>.</span></div>\n        <code class=\"mcode\">EID: 89049032005008882600123456789012</code>\n      </div>\n      <div class=\"msec\"><div class=\"msec-l\">Popular phones with eSIM</div>\n        <div class=\"mtags\"><span class=\"mtag tok\">✓ iPhone XS or later</span><span class=\"mtag tok\">✓ Galaxy S20 or later</span><span class=\"mtag tok\">✓ Galaxy Z Fold / Flip</span><span class=\"mtag tok\">✓ Pixel 3 or later</span><span class=\"mtag tok\">✓ iPad Pro / Air / mini (Cellular)</span></div>\n      </div>\n      <div class=\"msec\"><div class=\"msec-l\">Cannot use eSIM</div>\n        <div class=\"mtags\"><span class=\"mtag tno\">✕ iPhone 8 or earlier</span><span class=\"mtag tno\">✕ Mainland China iPhone models</span><span class=\"mtag tno\">✕ Carrier-locked phones</span><span class=\"mtag tno\">✕ Galaxy S10 or earlier</span></div>\n      </div>\n      <div class=\"mwarn\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#D97706\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg><span>Phones bought in Japan, the US or Korea are often <b>carrier-locked</b> — even with eSIM they won’t accept another carrier.</span></div>\n      <a class=\"mlink\" href=\"{{devices}}\">See the full list of eSIM-compatible devices<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"><path d=\"M5 12h14m-6-6 6 6-6 6\"/></svg></a>\n    </div>\n  </div>\n</div>\n\n<div class=\"ov\" id=\"ov-code\">\n  <div class=\"mdl\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"t-code\">\n    <div class=\"mdl-hd\"><div class=\"mdl-t\" id=\"t-code\">Where is my eSIM?</div><button class=\"mdl-x\" data-close=\"code\" aria-label=\"Close\" type=\"button\"><svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg></button></div>\n    <div class=\"mdl-b\">\n      <div class=\"msec\"><div class=\"msec-l\">Two places you can always find it</div>\n        <div class=\"mrow\"><div class=\"mdot\"></div><span><b>Confirmation email</b> — esim.vn sends it within <b>30 seconds</b> of payment, titled “Your eSIM is ready”. Check Spam and Promotions too.</span></div>\n        <div class=\"mrow\"><div class=\"mdot\"></div><span><b>On the esim.vn website</b> — Sign in → <b>Profile</b> → <b>Manage eSIM</b> → choose the plan → <b>View installation code</b>. The codes are always here, so a lost email is no problem.</span></div>\n      </div>\n      <div class=\"msec\"><div class=\"msec-l\">What’s inside?</div>\n        <div class=\"mrow\"><div class=\"mdot\"></div><span><b>Quick install button</b> for iOS and for Android — tap the right one for your phone and the eSIM installs itself.</span></div>\n        <div class=\"mrow\"><div class=\"mdot\"></div><span><b>QR code</b> — for scanning with another device.</span></div>\n        <div class=\"mrow\"><div class=\"mdot\"></div><span><b>SM-DP+ address</b> and <b>Activation code</b> — for the manual method.</span></div>\n        <code class=\"mcode\">SM-DP+: rsp.truphone.com<br>Activation code: QR-8F2K-4M9X-77PL</code>\n      </div>\n      <div class=\"mwarn\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#D97706\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg><span>Each eSIM can be installed only <b>once, on one phone</b>. Don’t share the code — whoever installs it first gets the eSIM.</span></div>\n    </div>\n  </div>\n</div>\n\n<div class=\"ov\" id=\"ov-term\">\n  <div class=\"mdl\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"t-term\">\n    <div class=\"mdl-hd\"><div class=\"mdl-t\" id=\"t-term\">Jargon explained simply</div><button class=\"mdl-x\" data-close=\"term\" aria-label=\"Close\" type=\"button\"><svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg></button></div>\n    <div class=\"mdl-b\">\n      <div class=\"msec\"><div class=\"msec-l\">eSIM</div><div class=\"mrow\"><div class=\"mdot\"></div><span>A digital SIM built into your phone’s chip. It does everything a plastic SIM does, with nothing to insert or remove.</span></div></div>\n      <div class=\"msec\"><div class=\"msec-l\">EID</div><div class=\"mrow\"><div class=\"mdot\"></div><span>The ID of the eSIM chip in your phone, made of <b>32 digits</b>. Dial <b>*#06#</b> to see it — if there is an EID, the phone can use eSIM.</span></div></div>\n      <div class=\"msec\"><div class=\"msec-l\">Quick install button</div><div class=\"mrow\"><div class=\"mdot\"></div><span>A special link supported by Apple and Google. Tap it and the phone opens the eSIM setup screen with everything filled in — nothing to type. Needs iOS 17.4+ or Android 10+.</span></div></div>\n      <div class=\"msec\"><div class=\"msec-l\">SM-DP+</div><div class=\"mrow\"><div class=\"mdot\"></div><span>The carrier server address your phone downloads the eSIM profile from. Just copy it exactly as written in the email.</span></div><code class=\"mcode\">rsp.truphone.com</code></div>\n      <div class=\"msec\"><div class=\"msec-l\">Activation code</div><div class=\"mrow\"><div class=\"mdot\"></div><span>A string of characters unique to your plan. Each code works only once, on one phone.</span></div></div>\n      <div class=\"msec\"><div class=\"msec-l\">ICCID</div><div class=\"mrow\"><div class=\"mdot\"></div><span>The ID of the eSIM itself, made of <b>19–20 digits</b>. Support often asks for it to look up your plan.</span></div><code class=\"mcode\">8984 1234 5678 9012 3</code></div>\n      <div class=\"msec\"><div class=\"msec-l\">Data Roaming</div><div class=\"mrow\"><div class=\"mdot\"></div><span>Lets your phone use a foreign carrier’s network. A travel eSIM <b>must</b> turn this on, and it does <b>not</b> cost anything extra, because you have prepaid.</span></div></div>\n    </div>\n  </div>\n</div>";
